const MAX_MENTIONS_PER_TURN: usize = 20;
const MAX_EXTERNAL_MENTION_FILE_BYTES: u64 = 25 * 1024 * 1024;
const MAX_EXTERNAL_MENTION_TURN_BYTES: u64 = 100 * 1024 * 1024;
const MAX_MENTION_DISCOVERY_ENTRIES: usize = 50_000;
const SPECIALIST_SUCCESS_CONDITION_POLICY: &str = "Every specialist success condition must describe an observable result the assigned specialist can independently verify before calling report_result. Never use outer task, request, conversation, coordination-batch, report-acceptance, integration-settlement, or owner-delivery completion as a specialist success condition.";

fn normalized_mention_relative_path(value: &str) -> Option<String> {
    let path = Path::new(value);
    if value.trim().is_empty() || path.is_absolute() {
        return None;
    }
    let mut parts = Vec::new();
    for component in path.components() {
        match component {
            Component::Normal(part) => parts.push(part.to_string_lossy().into_owned()),
            Component::CurDir => {}
            _ => return None,
        }
    }
    (!parts.is_empty()).then(|| parts.join("/"))
}

fn conversation_external_artifact_paths(view: &ConversationView) -> BTreeSet<String> {
    view.messages
        .iter()
        .flat_map(|message| message.mentions.iter())
        .filter_map(|mention| match &mention.target {
            MentionTarget::ExternalPath {
                artifact_relative_path: Some(relative_path),
                ..
            } => Some(relative_path.clone()),
            _ => None,
        })
        .collect()
}

fn remove_unreferenced_mention_artifact(data_directory: &Path, relative_path: &str) {
    let mut components = relative_path.split('/');
    let (Some(shard), Some(digest), None) =
        (components.next(), components.next(), components.next())
    else {
        return;
    };
    if shard.len() != 2
        || digest.len() != 64
        || !digest.bytes().all(|byte| byte.is_ascii_hexdigit())
        || !digest[..2].eq_ignore_ascii_case(shard)
    {
        return;
    }
    let artifacts = data_directory.join("artifacts");
    let shard_path = artifacts.join(shard);
    let artifact_path = shard_path.join(digest);
    let Ok(metadata) = fs::symlink_metadata(&artifact_path) else {
        return;
    };
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return;
    }
    if fs::remove_file(&artifact_path).is_ok() {
        let _ = fs::remove_dir(&shard_path);
    }
}

fn mention_path_excluded(relative: &str) -> bool {
    let normalized = relative.replace('\\', "/").to_ascii_lowercase();
    let components = normalized.split('/').collect::<Vec<_>>();
    components.iter().any(|component| {
        matches!(
            *component,
            ".git"
                | "node_modules"
                | "target"
                | "dist"
                | "build"
                | ".next"
                | ".cache"
                | ".venv"
                | "venv"
                | "__pycache__"
                | ".idea"
                | ".vscode"
        )
    }) || components.last().is_some_and(|name| {
        matches!(
            *name,
            ".env"
                | ".env.local"
                | ".env.production"
                | "credentials"
                | "credentials.json"
                | "id_rsa"
                | "id_ed25519"
        ) || name.ends_with(".pem")
            || name.ends_with(".p12")
            || name.ends_with(".pfx")
            || name.ends_with(".key")
    })
}

fn discover_project_mention_candidates(
    project_root: &Path,
) -> Result<Vec<MentionCandidate>, RuntimeError> {
    let root = fs::canonicalize(project_root)?;
    let mut stack = vec![root.clone()];
    let mut inspected = 0_usize;
    let mut candidates = Vec::new();
    while let Some(directory) = stack.pop() {
        let mut entries = fs::read_dir(&directory)?.collect::<Result<Vec<_>, _>>()?;
        entries.sort_by_key(std::fs::DirEntry::file_name);
        for entry in entries {
            inspected = inspected.saturating_add(1);
            if inspected > MAX_MENTION_DISCOVERY_ENTRIES {
                break;
            }
            let path = entry.path();
            let metadata = fs::symlink_metadata(&path)?;
            if metadata.file_type().is_symlink() {
                continue;
            }
            let relative = path.strip_prefix(&root).map_err(|_| {
                StorageError::InvalidData("project mention path escaped its root".into())
            })?;
            let relative = relative.to_string_lossy().replace('\\', "/");
            if mention_path_excluded(&relative) {
                continue;
            }
            if metadata.is_dir() {
                stack.push(path);
            } else if !metadata.is_file() {
                continue;
            }
            let label = relative
                .rsplit('/')
                .next()
                .unwrap_or(relative.as_str())
                .to_owned();
            candidates.push(MentionCandidate {
                kind: if metadata.is_dir() {
                    MentionKind::Folder
                } else {
                    MentionKind::File
                },
                label,
                resource: relative.clone(),
                detail: Some(relative),
                plugin_revision_id: None,
                installation_revision: None,
            });
        }
        if inspected > MAX_MENTION_DISCOVERY_ENTRIES {
            break;
        }
    }
    Ok(candidates)
}

fn mention_authority_context(mentions: &[ConversationMention]) -> String {
    if mentions.is_empty() {
        return String::new();
    }
    let rows = mentions
        .iter()
        .map(|mention| {
            format!(
                "- mention_id=`{}`; kind={:?}; label=`{}`",
                mention.id,
                mention.kind,
                mention.label.replace('`', "'")
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    format!(
        "\n\nExplicit owner references for this turn only:\n{rows}\nUse `read_mentioned_resource` or `list_mentioned_folder` on demand. Only the Chat Agent may use `invoke_mentioned_plugin`, and a plugin mention is not itself an invocation request. Include applicable mention IDs in Coordinator context references when delegating."
    )
}

fn validate_mention_entry_kind(
    kind: MentionKind,
    metadata: &fs::Metadata,
) -> Result<(), RuntimeError> {
    let valid = match kind {
        MentionKind::File => metadata.is_file(),
        MentionKind::Folder => metadata.is_dir(),
        MentionKind::Plugin => false,
    };
    if !valid {
        return Err(StorageError::InvalidData(
            "mentioned resource type does not match the selected item".into(),
        )
        .into());
    }
    Ok(())
}

fn observe_mention_metadata(
    path: &Path,
    metadata: &fs::Metadata,
    size: &mut Option<u64>,
    modified: &mut Option<i64>,
    sha256: &mut Option<String>,
) -> Result<(), RuntimeError> {
    *size = metadata.is_file().then_some(metadata.len());
    *modified = metadata
        .modified()
        .ok()
        .and_then(|time| time.duration_since(UNIX_EPOCH).ok())
        .and_then(|duration| i64::try_from(duration.as_millis()).ok());
    if metadata.is_file() && metadata.len() <= MAX_EXTERNAL_MENTION_FILE_BYTES {
        let bytes = fs::read(path)?;
        *sha256 = Some(format!("{:x}", Sha256::digest(bytes)));
    }
    Ok(())
}

