#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RuntimeState {
    Starting,
    Ready,
    Degraded,
    Stopping,
}

#[derive(Debug, Error)]
pub enum RuntimeError {
    #[error("runtime I/O failed: {0}")]
    Io(#[from] std::io::Error),
    #[error(transparent)]
    Storage(#[from] StorageError),
    #[error(transparent)]
    ProjectDiscovery(#[from] ProjectDiscoveryError),
    #[error(transparent)]
    Memory(#[from] MemoryError),
    #[error(transparent)]
    AgentTurn(#[from] AgentTurnError),
    #[error(transparent)]
    Provider(#[from] ProviderError),
    #[error("GitHub integration failed: {0}")]
    GitHub(String),
    #[error(transparent)]
    Mcp(#[from] McpError),
    #[error(transparent)]
    Tool(#[from] ToolError),
    #[error(transparent)]
    PluginTrust(#[from] PluginTrustError),
    #[error(transparent)]
    CodexHarness(#[from] CodexHarnessError),
    #[error("runtime storage lock was poisoned")]
    StorageLock,
    #[error("local authentication token is invalid")]
    InvalidAuthToken,
}

impl RuntimeError {
    #[must_use]
    pub const fn is_not_found(&self) -> bool {
        matches!(
            self,
            Self::Storage(
                StorageError::TaskNotFound(_)
                    | StorageError::ConversationNotFound(_)
                    | StorageError::ConversationTurnNotFound(_)
                    | StorageError::ProjectNotFound(_)
                    | StorageError::MemoryClaimNotFound(_)
                    | StorageError::OrganizationRevisionNotFound(_)
                    | StorageError::AgentRunNotFound(_)
                    | StorageError::AgentInstanceNotFound(_)
                    | StorageError::AgentLeaseNotFound(_)
                    | StorageError::ScheduleNotFound(_)
                    | StorageError::PlatformSessionNotFound(_)
                    | StorageError::SiteNotFound(_)
                    | StorageError::SshHostNotFound(_)
                    | StorageError::SshWorkflowNotFound(_)
                    | StorageError::BackupNotFound(_)
                    | StorageError::PluginNotFound(_)
                    | StorageError::PluginRevisionNotFound(_)
            )
        )
    }

    #[must_use]
    pub const fn is_invalid_request(&self) -> bool {
        matches!(
            self,
            Self::Storage(StorageError::InvalidTransition(_) | StorageError::InvalidData(_))
                | Self::ProjectDiscovery(_)
                | Self::Memory(
                    MemoryError::SecretNamespace
                        | MemoryError::InvalidConfidence
                        | MemoryError::EmptyKey
                        | MemoryError::InvalidTransfer(_)
                )
                | Self::AgentTurn(AgentTurnError::Invalid(_))
                | Self::Tool(ToolError::Invalid(_))
                | Self::PluginTrust(_)
                | Self::GitHub(_)
                | Self::CodexHarness(CodexHarnessError::InvalidRequest(_))
        )
    }

    #[must_use]
    pub const fn is_conflict(&self) -> bool {
        matches!(
            self,
            Self::Storage(StorageError::Conflict(_))
                | Self::Memory(MemoryError::InvalidTransition(_, _, _))
        )
    }
}

fn initialize_local_git_repository(root: &Path) -> Result<(), RuntimeError> {
    let canonical_root = fs::canonicalize(root)?;
    if !canonical_root.is_dir() {
        return Err(StorageError::InvalidData("project root must be a directory".into()).into());
    }

    let existing = Command::new("git")
        .args([
            "-C",
            canonical_root.to_string_lossy().as_ref(),
            "rev-parse",
            "--show-toplevel",
        ])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()?;
    if existing.success() {
        let head = Command::new("git")
            .args([
                "-C",
                canonical_root.to_string_lossy().as_ref(),
                "rev-parse",
                "--verify",
                "HEAD",
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()?;
        if head.success() {
            return Ok(());
        }
        let commit = Command::new("git")
            .args([
                "-C",
                canonical_root.to_string_lossy().as_ref(),
                "-c",
                "user.name=MCG",
                "-c",
                "user.email=mcg@local.invalid",
                "commit",
                "--allow-empty",
                "-m",
                "Initialize local version history",
            ])
            .stdin(Stdio::null())
            .output()?;
        if commit.status.success() {
            return Ok(());
        }
        return Err(StorageError::InvalidData(format!(
            "existing local Git repository has no baseline commit and MCG could not create one: {}",
            String::from_utf8_lossy(&commit.stderr).trim()
        ))
        .into());
    }

    let git_directory = canonical_root.join(".git");
    if git_directory.exists() {
        return Err(StorageError::InvalidData(
            "project contains Git metadata that Git cannot read; MCG left it unchanged".into(),
        )
        .into());
    }

    let init = Command::new("git")
        .args([
            "-C",
            canonical_root.to_string_lossy().as_ref(),
            "init",
            "-b",
            "main",
        ])
        .stdin(Stdio::null())
        .output()?;
    if !init.status.success() {
        return Err(StorageError::InvalidData(format!(
            "local Git initialization failed: {}",
            String::from_utf8_lossy(&init.stderr).trim()
        ))
        .into());
    }

    let commit = Command::new("git")
        .args([
            "-C",
            canonical_root.to_string_lossy().as_ref(),
            "-c",
            "user.name=MCG",
            "-c",
            "user.email=mcg@local.invalid",
            "commit",
            "--allow-empty",
            "-m",
            "Initialize local version history",
        ])
        .stdin(Stdio::null())
        .output()?;
    if commit.status.success() {
        return Ok(());
    }

    // Roll back only the exact metadata directory created above. Source files
    // were never staged or modified by this operation.
    if git_directory.parent() == Some(canonical_root.as_path()) && git_directory.is_dir() {
        fs::remove_dir_all(&git_directory)?;
    }
    Err(StorageError::InvalidData(format!(
        "local Git initialization could not create its empty baseline commit: {}",
        String::from_utf8_lossy(&commit.stderr).trim()
    ))
    .into())
}

