#[derive(Clone)]
struct RuntimeMcpExecutor {
    store: Arc<Mutex<SqliteEventStore>>,
    credentials: Arc<dyn McpCredentialStore>,
}

#[async_trait]
impl ToolExecutor for RuntimeMcpExecutor {
    async fn execute(
        &self,
        execution_id: ToolExecutionId,
        request: &ToolRequest,
    ) -> Result<ToolOutcome, ToolError> {
        let ToolRequestKind::McpCall {
            connection_id,
            tool_name,
            arguments,
            read_only,
            destructive,
            open_world,
        } = &request.kind
        else {
            return Err(ToolError::Invalid(
                "external MCP executor received a non-MCP request".into(),
            ));
        };
        let (mut connection, descriptor, protocol_version) = {
            let store = self
                .store
                .lock()
                .map_err(|_| ToolError::Execution("runtime storage lock was poisoned".into()))?;
            let connection = store
                .mcp_connection(connection_id)
                .map_err(|error| ToolError::Execution(error.to_string()))?
                .ok_or_else(|| ToolError::Invalid("MCP connection was not found".into()))?;
            let catalog = store
                .mcp_catalog(connection_id)
                .map_err(|error| ToolError::Execution(error.to_string()))?
                .ok_or_else(|| ToolError::Invalid("MCP tool catalog was not found".into()))?;
            let protocol_version = catalog.protocol_version.clone();
            let descriptor = catalog
                .tools
                .into_iter()
                .find(|tool| tool.name == *tool_name)
                .ok_or_else(|| ToolError::Invalid("MCP tool was not discovered".into()))?;
            (connection, descriptor, protocol_version)
        };
        if !connection.enabled {
            return Err(ToolError::Denied("MCP connection is disabled".into()));
        }
        let classification = mcp_tool_classification(&descriptor.annotations);
        if classification != (*read_only, *destructive, *open_world) {
            return Err(ToolError::Denied(
                "MCP tool classification changed after authority was issued".into(),
            ));
        }
        let credential = load_mcp_credential(self.credentials.as_ref(), &connection)
            .map_err(|error| ToolError::Execution(error.to_string()))?;
        connection.protocol_mode = protocol_mode_for_catalog(&protocol_version)
            .map_err(|error| ToolError::Execution(error.to_string()))?;
        let client = McpClient::new(connection, credential)
            .map_err(|error| ToolError::Execution(error.to_string()))?;
        let started_at = Utc::now();
        let result = client
            .call_tool(tool_name, arguments.clone())
            .await
            .map_err(|error| ToolError::Execution(error.to_string()))?;
        let finished_at = Utc::now();
        let stdout = serde_json::to_string(&result)
            .map_err(|error| ToolError::Execution(error.to_string()))?;
        Ok(ToolOutcome {
            schema_version: TOOL_SCHEMA_VERSION,
            execution_id,
            request_id: request.id,
            status: if result.is_error {
                ToolOutcomeStatus::Failed
            } else {
                ToolOutcomeStatus::Succeeded
            },
            summary: if result.is_error {
                format!("MCP tool {tool_name} returned an error result")
            } else {
                format!("MCP tool {tool_name} completed")
            },
            exit_code: None,
            stdout: Some(stdout),
            stderr: None,
            artifacts: Vec::new(),
            verification: vec![VerificationEvidence {
                method: "mcp.tool_result".into(),
                passed: !result.is_error,
                detail: format!("connection={connection_id}; tool={tool_name}"),
            }],
            started_at,
            finished_at,
        })
    }
}

#[derive(Clone)]
pub struct RuntimeProviderGateway {
    registry: Arc<tokio::sync::RwLock<ProviderRegistry>>,
    oauth_refresh: Arc<OAuthRefreshCoordinator>,
}

enum ProtectedProviderCredentialSnapshot {
    None,
    Primary(ProviderCredential),
    OAuth(OAuthTokenSet),
}

impl RuntimeProviderGateway {
    /// Streams from one exact route selected by the caller-side router.
    ///
    /// # Errors
    ///
    /// Returns provider configuration, authentication, transport, or protocol errors.
    pub async fn stream_response(
        &self,
        target: &ProviderModelRef,
        request: ModelRequest,
    ) -> Result<mcg_providers::ProviderStream, ProviderError> {
        let initial = self
            .registry
            .read()
            .await
            .stream_response(target, request.clone())
            .await;
        if !matches!(initial, Err(ProviderError::Authentication(_))) {
            return initial;
        }
        if !self.refresh_after_authentication_failure(target).await? {
            return initial;
        }
        self.registry
            .read()
            .await
            .stream_response(target, request)
            .await
    }

    async fn refresh_after_authentication_failure(
        &self,
        target: &ProviderModelRef,
    ) -> Result<bool, ProviderError> {
        self.oauth_refresh
            .refresh_after_authentication_failure(&target.provider_id)
            .await
            .map_err(|error| match error {
                RuntimeError::Provider(error) => error,
                error => ProviderError::Authentication(format!(
                    "automatic OAuth refresh failed without changing billing mode: {error}"
                )),
            })
    }
}

impl std::fmt::Debug for RuntimeProviderGateway {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("RuntimeProviderGateway")
            .finish_non_exhaustive()
    }
}

#[async_trait]
impl AgentModelGateway for RuntimeProviderGateway {
    async fn create_response(
        &self,
        target: &ProviderModelRef,
        request: ModelRequest,
    ) -> Result<ModelResponse, ProviderError> {
        let initial = self
            .registry
            .read()
            .await
            .create_response(target, request.clone())
            .await;
        if !matches!(initial, Err(ProviderError::Authentication(_))) {
            return initial;
        }
        if !self.refresh_after_authentication_failure(target).await? {
            return initial;
        }
        self.registry
            .read()
            .await
            .create_response(target, request)
            .await
    }
}

#[derive(Clone)]
pub struct LocalAuth {
    token: String,
}

impl std::fmt::Debug for LocalAuth {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.debug_struct("LocalAuth").finish_non_exhaustive()
    }
}

impl LocalAuth {
    const MINIMUM_TOKEN_LENGTH: usize = 32;

    /// Loads an existing local token or creates a private one.
    ///
    /// # Errors
    ///
    /// Returns an error for unreadable, invalid, or unwritable token files.
    pub fn load_or_create(path: &Path) -> Result<Self, RuntimeError> {
        if path.exists() {
            restrict_to_owner(path, 0o600)?;
            let mut token = String::new();
            OpenOptions::new()
                .read(true)
                .open(path)?
                .read_to_string(&mut token)?;
            return Self::from_token(token.trim().to_owned());
        }

        let token = format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple());
        let mut options = OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            options.mode(0o600);
        }
        let mut file = options.open(path)?;
        file.write_all(token.as_bytes())?;
        file.sync_all()?;
        Self::from_token(token)
    }

    /// Creates an in-memory authenticator for deterministic tests.
    ///
    /// # Errors
    ///
    /// Rejects tokens too short for local bearer authentication.
    pub fn from_token(token: String) -> Result<Self, RuntimeError> {
        if token.len() < Self::MINIMUM_TOKEN_LENGTH {
            return Err(RuntimeError::InvalidAuthToken);
        }
        Ok(Self { token })
    }

    #[must_use]
    pub fn verifies(&self, candidate: &str) -> bool {
        candidate.len() == self.token.len()
            && bool::from(candidate.as_bytes().ct_eq(self.token.as_bytes()))
    }

    #[must_use]
    pub fn token_for_local_client(&self) -> &str {
        &self.token
    }
}

#[async_trait]
trait PluginRunnerGateway: Send + Sync {
    async fn invoke(
        &self,
        request: &PluginRunnerRequest,
    ) -> Result<PluginRunnerResponse, PluginRunnerClientError>;
}

struct ProcessPluginRunnerGateway(PluginRunnerClient);

#[async_trait]
impl PluginRunnerGateway for ProcessPluginRunnerGateway {
    async fn invoke(
        &self,
        request: &PluginRunnerRequest,
    ) -> Result<PluginRunnerResponse, PluginRunnerClientError> {
        self.0.invoke(request).await
    }
}

fn package_plugin_runner() -> Option<Arc<dyn PluginRunnerGateway>> {
    let application = std::env::current_exe().ok()?;
    let client = PluginRunnerClient::adjacent_to(application).ok()?;
    Some(Arc::new(ProcessPluginRunnerGateway(client)))
}

#[derive(Clone)]
struct ProviderToolCredentialResolver {
    store: Arc<dyn ProviderCredentialStore>,
}

#[async_trait]
impl CredentialResolver for ProviderToolCredentialResolver {
    async fn resolve(&self, reference: &CredentialReference) -> Result<SecretMaterial, ToolError> {
        let slot = match reference.key.as_str() {
            "primary" => ProviderSecretSlot::Primary,
            "oauth_id_token" => ProviderSecretSlot::OAuthIdToken,
            "oauth_refresh_token" => ProviderSecretSlot::OAuthRefreshToken,
            _ => {
                return Err(ToolError::Denied(format!(
                    "credential key {}/{} is unsupported",
                    reference.provider, reference.key
                )));
            }
        };
        let credential = self
            .store
            .load(&reference.provider, slot)
            .map_err(|error| ToolError::Execution(error.to_string()))?
            .ok_or_else(|| {
                ToolError::Denied(format!(
                    "credential reference {}/{} is unavailable",
                    reference.provider, reference.key
                ))
            })?;
        SecretMaterial::new(credential.expose_to_host_executor())
    }
}

fn validate_plugin_invocation_replay(
    invocation: &PluginInvocationRecord,
    plugin_id: &str,
    task_id: Option<TaskId>,
    input_sha256: &str,
) -> Result<(), StorageError> {
    if invocation.plugin_id != plugin_id
        || invocation.task_id != task_id
        || invocation.input_sha256 != input_sha256
    {
        return Err(StorageError::Conflict(format!(
            "plugin invocation {} was reused with different input",
            invocation.id
        )));
    }
    Ok(())
}

const fn plugin_runner_failure(
    error: &PluginRunnerClientError,
    capability_executed: bool,
) -> (PluginInvocationState, &'static str) {
    if capability_executed {
        return (PluginInvocationState::Uncertain, "runner_uncertain");
    }
    match error {
        PluginRunnerClientError::Unavailable | PluginRunnerClientError::RequestTooLarge => {
            (PluginInvocationState::Failed, "runner_unavailable")
        }
        PluginRunnerClientError::Timeout
        | PluginRunnerClientError::ResponseTooLarge
        | PluginRunnerClientError::DiagnosticOutput
        | PluginRunnerClientError::InvalidResponse
        | PluginRunnerClientError::Process => {
            (PluginInvocationState::Uncertain, "runner_uncertain")
        }
    }
}

fn plugin_tool_kind(
    operation: &PluginCapabilityOperation,
    grants: &[PluginCapabilityGrant],
    project_root: &Path,
) -> Result<ToolRequestKind, ToolError> {
    for capability in operation.required_capabilities() {
        if !grants.iter().any(|grant| grant.capability == capability) {
            return Err(ToolError::Denied(format!(
                "plugin capability {capability:?} is not granted"
            )));
        }
    }
    match operation {
        PluginCapabilityOperation::FilesystemRead { path, max_bytes } => {
            require_task_project_grant(grants, PluginCapability::FilesystemRead)?;
            Ok(ToolRequestKind::FsRead {
                path: plugin_project_path(project_root, path, false)?,
                max_bytes: *max_bytes,
            })
        }
        PluginCapabilityOperation::FilesystemWrite {
            path,
            content,
            create_new,
        } => {
            require_task_project_grant(grants, PluginCapability::FilesystemWrite)?;
            Ok(ToolRequestKind::FsWrite {
                path: plugin_project_path(project_root, path, false)?,
                content: content.clone(),
                create_new: *create_new,
            })
        }
        PluginCapabilityOperation::HttpRequest {
            method,
            url,
            headers,
            body,
            max_response_bytes,
        } => {
            let parsed = url::Url::parse(url)
                .map_err(|_| ToolError::Invalid("plugin HTTP URL is invalid".into()))?;
            let origin = parsed.origin().ascii_serialization();
            if !grant_scopes(grants, PluginCapability::Network).any(|scope| {
                matches!(scope, PluginCapabilityScope::NetworkOrigin { origin: allowed } if allowed == &origin)
            }) {
                return Err(ToolError::Denied(format!(
                    "plugin network origin {origin} is not granted"
                )));
            }
            Ok(ToolRequestKind::HttpRequest {
                method: method.clone(),
                url: url.clone(),
                headers: headers
                    .iter()
                    .map(|header| {
                        Ok(mcg_tools::RequestHeader {
                            name: header.name.clone(),
                            value: plugin_value_source(&header.value, grants)?,
                        })
                    })
                    .collect::<Result<Vec<_>, ToolError>>()?,
                body: body.clone(),
                max_response_bytes: *max_response_bytes,
            })
        }
        PluginCapabilityOperation::ProcessExec {
            executable,
            argv,
            cwd,
            env,
            stdin,
        } => {
            if !grant_scopes(grants, PluginCapability::Process).any(|scope| {
                matches!(scope, PluginCapabilityScope::Executable { executable: allowed } if allowed.eq_ignore_ascii_case(executable))
            }) {
                return Err(ToolError::Denied(format!(
                    "plugin executable {executable} is not granted"
                )));
            }
            Ok(ToolRequestKind::ProcessExec {
                options: ProcessOptions {
                    executable: executable.clone(),
                    argv: argv.clone(),
                    cwd: plugin_project_path(project_root, cwd, true)?,
                    env: env
                        .iter()
                        .map(|variable| {
                            Ok(ProcessEnvironmentVariable {
                                name: variable.name.clone(),
                                value: plugin_value_source(&variable.value, grants)?,
                            })
                        })
                        .collect::<Result<Vec<_>, ToolError>>()?,
                    stdin: if stdin.is_some() {
                        ProcessStream::Piped
                    } else {
                        ProcessStream::Null
                    },
                    stdin_data: stdin.clone(),
                    stdout: ProcessStream::Piped,
                    stderr: ProcessStream::Piped,
                },
            })
        }
    }
}

fn grant_scopes(
    grants: &[PluginCapabilityGrant],
    capability: PluginCapability,
) -> impl Iterator<Item = &PluginCapabilityScope> {
    grants
        .iter()
        .filter(move |grant| grant.capability == capability)
        .flat_map(|grant| grant.scopes.iter())
}

fn require_task_project_grant(
    grants: &[PluginCapabilityGrant],
    capability: PluginCapability,
) -> Result<(), ToolError> {
    if grant_scopes(grants, capability)
        .any(|scope| matches!(scope, PluginCapabilityScope::TaskProject))
    {
        Ok(())
    } else {
        Err(ToolError::Denied(format!(
            "plugin {capability:?} task-project scope is not granted"
        )))
    }
}

fn plugin_value_source(
    source: &PluginValueSource,
    grants: &[PluginCapabilityGrant],
) -> Result<HeaderValue, ToolError> {
    match source {
        PluginValueSource::Literal(value) => Ok(HeaderValue::Literal(value.clone())),
        PluginValueSource::Credential(reference) => {
            if !grant_scopes(grants, PluginCapability::Credentials).any(|scope| {
                matches!(
                    scope,
                    PluginCapabilityScope::Credential { provider, key }
                    if provider == &reference.provider && key == &reference.key
                )
            }) {
                return Err(ToolError::Denied(format!(
                    "plugin credential reference {}/{} is not granted",
                    reference.provider, reference.key
                )));
            }
            Ok(HeaderValue::Credential(CredentialReference {
                provider: reference.provider.clone(),
                key: reference.key.clone(),
            }))
        }
    }
}

fn plugin_project_path(
    project_root: &Path,
    relative: &str,
    allow_root: bool,
) -> Result<String, ToolError> {
    let path = Path::new(relative);
    let mut normalized = std::path::PathBuf::new();
    for component in path.components() {
        match component {
            std::path::Component::Normal(value) => normalized.push(value),
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir
            | std::path::Component::RootDir
            | std::path::Component::Prefix(_) => {
                return Err(ToolError::Denied(
                    "plugin project path escapes its task project".into(),
                ));
            }
        }
    }
    if normalized.as_os_str().is_empty() && !allow_root {
        return Err(ToolError::Invalid("plugin project path is empty".into()));
    }
    Ok(project_root.join(normalized).to_string_lossy().into_owned())
}

fn plugin_capability_policy(
    grants: &[PluginCapabilityGrant],
    project_root: &Path,
) -> CapabilityPolicy {
    let mut policy = CapabilityPolicy::project(project_root);
    policy.filesystem_read_roots.clear();
    policy.filesystem_write_roots.clear();
    policy.allowed_executables.clear();
    policy.allowed_shells.clear();
    policy.allowed_network_origins.clear();
    policy.allow_shell = false;
    policy.allow_git_mutation = false;
    policy.managed_process_control = mcg_policy::CapabilityAccess::Denied;
    policy.system_inspection = mcg_policy::CapabilityAccess::Denied;
    for grant in grants {
        for scope in &grant.scopes {
            match (grant.capability, scope) {
                (PluginCapability::FilesystemRead, PluginCapabilityScope::TaskProject) => {
                    policy
                        .filesystem_read_roots
                        .push(project_root.to_path_buf());
                }
                (PluginCapability::FilesystemWrite, PluginCapabilityScope::TaskProject) => {
                    policy
                        .filesystem_write_roots
                        .push(project_root.to_path_buf());
                }
                (PluginCapability::Network, PluginCapabilityScope::NetworkOrigin { origin }) => {
                    policy.allowed_network_origins.push(origin.clone());
                }
                (PluginCapability::Process, PluginCapabilityScope::Executable { executable }) => {
                    policy.allowed_executables.push(executable.clone());
                }
                _ => {}
            }
        }
    }
    policy
}

fn plugin_tool_outcome(outcome: &ToolOutcome) -> serde_json::Value {
    serde_json::json!({
        "status": outcome.status,
        "summary": bounded_plugin_output_text(&outcome.summary, 4_096),
        "exit_code": outcome.exit_code,
        "stdout": outcome.stdout.as_deref().map(|value| bounded_plugin_output_text(value, 48 * 1_024)),
        "stderr": outcome.stderr.as_deref().map(|value| bounded_plugin_output_text(value, 48 * 1_024)),
        "artifacts": outcome.artifacts.iter().take(16).collect::<Vec<_>>(),
        "verification": outcome.verification.iter().take(16).map(|evidence| serde_json::json!({
            "method": bounded_plugin_output_text(&evidence.method, 256),
            "passed": evidence.passed,
            "detail": bounded_plugin_output_text(&evidence.detail, 1_024),
        })).collect::<Vec<_>>(),
    })
}

fn bounded_plugin_output_text(value: &str, maximum_bytes: usize) -> String {
    if value.len() <= maximum_bytes {
        return value.to_owned();
    }
    let mut end = maximum_bytes;
    while !value.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}[TRUNCATED]", &value[..end])
}

#[derive(Debug, Deserialize)]
#[serde(tag = "action", rename_all = "snake_case")]
enum ChatAgentDecision {
    Respond {
        response: String,
    },
    DelegateCode {
        objective: String,
        #[serde(default)]
        scope: Vec<String>,
        #[serde(default)]
        constraints: Vec<String>,
        #[serde(default)]
        success_conditions: Vec<String>,
        #[serde(default)]
        context_references: Vec<String>,
    },
}

fn parse_chat_agent_decision(value: &str) -> Option<ChatAgentDecision> {
    let value = value.trim();
    if value.is_empty() {
        return None;
    }
    serde_json::from_str(value)
        .ok()
        .or_else(|| {
            let fenced = value
                .strip_prefix("```json")
                .or_else(|| value.strip_prefix("```"))?
                .strip_suffix("```")?
                .trim();
            serde_json::from_str(fenced).ok()
        })
        .or_else(|| {
            // Codex 0.150.1 can satisfy an output-schema turn with the selected enum tag as
            // the first line and the selected string payload as the remaining text instead of
            // publishing the JSON object. Accept only that exact compatibility envelope. A
            // narrow marker prevents ordinary prose that merely mentions delegation from
            // acquiring coding authority.
            let (action, payload) = value.split_once('\n')?;
            let payload = payload.trim();
            if payload.is_empty() {
                return None;
            }
            match action.trim() {
                "respond" => Some(ChatAgentDecision::Respond {
                    response: payload.to_owned(),
                }),
                "delegate_code" => Some(ChatAgentDecision::DelegateCode {
                    objective: payload.to_owned(),
                    scope: Vec::new(),
                    constraints: Vec::new(),
                    success_conditions: Vec::new(),
                    context_references: Vec::new(),
                }),
                _ => None,
            }
        })
}

fn parse_completed_compatibility_fallback(
    two_agent_conversations: bool,
    turn_state: ConversationTurnState,
    value: &str,
) -> Option<ChatAgentDecision> {
    if two_agent_conversations || turn_state != ConversationTurnState::Completed {
        return None;
    }
    parse_chat_agent_decision(value)
}

fn chat_agent_decision_schema() -> serde_json::Value {
    serde_json::json!({
        "type": "object",
        "oneOf": [
            {
                "properties": {
                    "action": {"const": "respond"},
                    "response": {"type": "string", "minLength": 1}
                },
                "required": ["action", "response"],
                "additionalProperties": false
            },
            {
                "properties": {
                    "action": {"const": "delegate_code"},
                    "objective": {"type": "string", "minLength": 1},
                    "scope": {"type": "array", "items": {"type": "string"}},
                    "constraints": {"type": "array", "items": {"type": "string"}},
                    "success_conditions": {"type": "array", "items": {"type": "string"}},
                    "context_references": {"type": "array", "items": {"type": "string"}}
                },
                "required": ["action", "objective", "scope", "constraints", "success_conditions", "context_references"],
                "additionalProperties": false
            }
        ]
    })
}

fn git_output(root: &Path, arguments: &[&str]) -> Result<Vec<u8>, StorageError> {
    for attempt in 0..3 {
        let output = Command::new("git")
            .args(arguments)
            .current_dir(root)
            .output()
            .map_err(StorageError::Io)?;
        if output.status.success() {
            return Ok(output.stdout);
        }
        if transient_git_process_failure(&output.status) && attempt < 2 {
            std::thread::sleep(StdDuration::from_millis(100_u64 << attempt));
            continue;
        }
        let stderr = String::from_utf8_lossy(&output.stderr).trim().to_owned();
        let stdout = String::from_utf8_lossy(&output.stdout).trim().to_owned();
        return Err(StorageError::InvalidData(format!(
            "Git command `git {}` failed with status {} after {} attempt(s): {}",
            arguments.join(" "),
            output.status,
            attempt + 1,
            if stderr.is_empty() { &stdout } else { &stderr }
        )));
    }
    unreachable!("bounded Git retry loop always returns")
}

fn git_with_input(root: &Path, arguments: &[&str], input: &[u8]) -> Result<(), StorageError> {
    for attempt in 0..3 {
        let mut child = Command::new("git")
            // Integration patches are authoritative byte streams. Never let a
            // host-global checkout preference rewrite LF to CRLF while applying
            // an accepted specialist or cloud patch.
            .args(["-c", "core.autocrlf=false"])
            .args(arguments)
            .current_dir(root)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(StorageError::Io)?;
        child
            .stdin
            .take()
            .ok_or_else(|| StorageError::InvalidData("Git stdin was unavailable".into()))?
            .write_all(input)
            .map_err(StorageError::Io)?;
        let output = child.wait_with_output().map_err(StorageError::Io)?;
        if output.status.success() {
            return Ok(());
        }
        if transient_git_process_failure(&output.status) && attempt < 2 {
            std::thread::sleep(StdDuration::from_millis(100_u64 << attempt));
            continue;
        }
        return Err(StorageError::InvalidData(format!(
            "Git command `git {}` failed with status {} after {} attempt(s): {}",
            arguments.join(" "),
            output.status,
            attempt + 1,
            String::from_utf8_lossy(&output.stderr).trim()
        )));
    }
    unreachable!("bounded Git retry loop always returns")
}

fn transient_git_process_failure(status: &std::process::ExitStatus) -> bool {
    #[cfg(windows)]
    {
        // STATUS_DLL_INIT_FAILED. Git for Windows can return this transiently when multiple
        // isolated worktrees launch Git at the same instant under host process pressure.
        status.code() == Some(-1_073_741_502)
    }
    #[cfg(not(windows))]
    {
        let _ = status;
        false
    }
}

fn generated_agent_artifact_path(relative: &str) -> bool {
    let normalized = relative.replace('\\', "/").to_ascii_lowercase();
    normalized.starts_with("chrome-temp/")
        || normalized.starts_with("playwright-report/")
        || normalized.starts_with("test-results/")
        || matches!(
            normalized.as_str(),
            "site-preview.png" | "site-screenshot.png"
        )
}

fn include_untracked_in_worktree_diff(root: &Path) -> Result<(), StorageError> {
    // Intent-to-add makes eligible new source visible to `git diff --binary` without staging its
    // contents. Verification profiles/screenshots remain evidence in the retained worktree, while
    // sensitive paths and ignored/generated output can never enter the integration patch.
    let untracked = git_output(root, &["ls-files", "--others", "--exclude-standard", "-z"])?;
    for relative in untracked
        .split(|byte| *byte == 0)
        .filter(|value| !value.is_empty())
    {
        let relative = std::str::from_utf8(relative)
            .map_err(|_| StorageError::InvalidData("untracked Git path is not UTF-8".into()))?;
        if sensitive_baseline_path(relative) || generated_agent_artifact_path(relative) {
            continue;
        }
        git_output(root, &["add", "--intent-to-add", "--", relative])?;
    }
    Ok(())
}

fn touches_untracked_baseline(
    touched_paths: &[mcg_domain::IntegrationTouchedPath],
    baseline_entries: &[mcg_domain::WorktreeBaselineEntry],
) -> bool {
    touched_paths.iter().any(|touched| {
        baseline_entries.iter().any(|baseline| {
            baseline.normalized_path == touched.normalized_path
                && baseline.source_kind == mcg_domain::BaselineSourceKind::Untracked
        })
    })
}

fn sensitive_baseline_path(relative: &str) -> bool {
    let normalized = relative.replace('\\', "/").to_ascii_lowercase();
    let file_name = Path::new(relative)
        .file_name()
        .and_then(std::ffi::OsStr::to_str)
        .unwrap_or_default()
        .to_ascii_lowercase();
    file_name == ".env"
        || file_name.starts_with(".env.")
        || [".pem", ".key", ".p12", ".pfx", ".kdbx"]
            .iter()
            .any(|extension| file_name.ends_with(extension))
        || normalized
            .split('/')
            .any(|part| matches!(part, ".git" | ".ssh" | "credentials" | "secrets"))
}

fn baseline_entry(
    repository: &Path,
    relative: &str,
    source_kind: mcg_domain::BaselineSourceKind,
) -> Result<mcg_domain::WorktreeBaselineEntry, StorageError> {
    let source = repository.join(relative);
    if !source.exists() {
        return Ok(mcg_domain::WorktreeBaselineEntry {
            normalized_path: relative.replace('\\', "/"),
            source_kind,
            size: 0,
            mode: 0,
            sha256: format!("{:x}", Sha256::digest([])),
        });
    }
    let metadata = fs::symlink_metadata(&source).map_err(StorageError::Io)?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err(StorageError::InvalidData(format!(
            "baseline path {relative} is symlinked or not a regular file"
        )));
    }
    let bytes = fs::read(&source).map_err(StorageError::Io)?;
    #[cfg(unix)]
    let mode = {
        use std::os::unix::fs::PermissionsExt;
        metadata.permissions().mode()
    };
    #[cfg(not(unix))]
    let mode = 0;
    Ok(mcg_domain::WorktreeBaselineEntry {
        normalized_path: relative.replace('\\', "/"),
        source_kind,
        size: metadata.len(),
        mode,
        sha256: format!("{:x}", Sha256::digest(&bytes)),
    })
}

fn tracked_baseline_manifest(
    repository: &Path,
) -> Result<Vec<mcg_domain::WorktreeBaselineEntry>, StorageError> {
    let changed = git_output(repository, &["diff", "--name-only", "-z", "HEAD", "--"])?;
    let mut entries = Vec::new();
    for relative in changed
        .split(|byte| *byte == 0)
        .filter(|value| !value.is_empty())
    {
        let relative = std::str::from_utf8(relative)
            .map_err(|_| StorageError::InvalidData("tracked Git path is not UTF-8".into()))?;
        if sensitive_baseline_path(relative) {
            return Err(StorageError::InvalidData(format!(
                "tracked sensitive path {relative} cannot enter a Coding Agent baseline"
            )));
        }
        let entry = baseline_entry(
            repository,
            relative,
            mcg_domain::BaselineSourceKind::Tracked,
        )?;
        if entry.size > 10 * 1024 * 1024 {
            return Err(StorageError::InvalidData(format!(
                "tracked path {relative} exceeds the 10 MiB Coding Agent baseline limit"
            )));
        }
        entries.push(entry);
    }
    Ok(entries)
}

fn bounded_untracked_overlay(
    repository: &Path,
    worktree: &Path,
) -> Result<
    (
        Vec<mcg_domain::WorktreeBaselineEntry>,
        Vec<mcg_domain::WorktreeBaselineExclusion>,
    ),
    StorageError,
> {
    let untracked = git_output(
        repository,
        &["ls-files", "--others", "--exclude-standard", "-z"],
    )?;
    let mut entries = Vec::new();
    let mut exclusions = Vec::new();
    for relative in untracked
        .split(|byte| *byte == 0)
        .filter(|value| !value.is_empty())
    {
        let relative = std::str::from_utf8(relative)
            .map_err(|_| StorageError::InvalidData("untracked Git path is not UTF-8".into()))?;
        if sensitive_baseline_path(relative) {
            exclusions.push(mcg_domain::WorktreeBaselineExclusion {
                normalized_path: relative.replace('\\', "/"),
                reason: "sensitive path excluded".into(),
                review_blocker: true,
            });
            continue;
        }
        let source = repository.join(relative);
        let destination = worktree.join(relative);
        let source_metadata = fs::symlink_metadata(&source).map_err(StorageError::Io)?;
        if source_metadata.file_type().is_symlink() || !source_metadata.is_file() {
            exclusions.push(mcg_domain::WorktreeBaselineExclusion {
                normalized_path: relative.replace('\\', "/"),
                reason: "symlinked or non-regular path excluded".into(),
                review_blocker: true,
            });
            continue;
        }
        let source = source.canonicalize().map_err(StorageError::Io)?;
        let repository = repository.canonicalize().map_err(StorageError::Io)?;
        let metadata = fs::symlink_metadata(&source).map_err(StorageError::Io)?;
        if !source.starts_with(&repository)
            || metadata.file_type().is_symlink()
            || !metadata.is_file()
        {
            exclusions.push(mcg_domain::WorktreeBaselineExclusion {
                normalized_path: relative.replace('\\', "/"),
                reason: "symlinked, escaped, or non-regular path excluded".into(),
                review_blocker: true,
            });
            continue;
        }
        if metadata.len() > 10 * 1024 * 1024 {
            exclusions.push(mcg_domain::WorktreeBaselineExclusion {
                normalized_path: relative.replace('\\', "/"),
                reason: "file exceeds 10 MiB baseline limit".into(),
                review_blocker: true,
            });
            continue;
        }
        if let Some(parent) = destination.parent() {
            fs::create_dir_all(parent).map_err(StorageError::Io)?;
        }
        fs::copy(source, destination).map_err(StorageError::Io)?;
        entries.push(baseline_entry(
            &repository,
            relative,
            mcg_domain::BaselineSourceKind::Untracked,
        )?);
    }
    Ok((entries, exclusions))
}

fn directory_size_bytes(root: &Path) -> Result<u64, StorageError> {
    let mut total = 0_u64;
    let mut pending = vec![root.to_path_buf()];
    while let Some(directory) = pending.pop() {
        for entry in fs::read_dir(directory).map_err(StorageError::Io)? {
            let entry = entry.map_err(StorageError::Io)?;
            let file_type = entry.file_type().map_err(StorageError::Io)?;
            if file_type.is_symlink() {
                continue;
            }
            if file_type.is_dir() {
                pending.push(entry.path());
            } else if file_type.is_file() {
                total = total.saturating_add(entry.metadata().map_err(StorageError::Io)?.len());
            }
        }
    }
    Ok(total)
}

fn direct_workspace_ignored_path(relative: &str) -> bool {
    relative.replace('\\', "/").split('/').any(|part| {
        matches!(
            part.to_ascii_lowercase().as_str(),
            ".git"
                | "node_modules"
                | "target"
                | "dist"
                | "build"
                | ".next"
                | "coverage"
                | ".venv"
                | "venv"
                | "__pycache__"
        )
    })
}

fn direct_workspace_snapshot(
    source: &Path,
    destination: Option<&Path>,
) -> Result<
    (
        Vec<mcg_domain::WorktreeBaselineEntry>,
        Vec<mcg_domain::WorktreeBaselineExclusion>,
    ),
    StorageError,
> {
    let canonical_source = fs::canonicalize(source).map_err(StorageError::Io)?;
    let mut pending = vec![canonical_source.clone()];
    let mut entries = Vec::new();
    let mut exclusions = Vec::new();
    while let Some(directory) = pending.pop() {
        for entry in fs::read_dir(&directory).map_err(StorageError::Io)? {
            let entry = entry.map_err(StorageError::Io)?;
            let path = entry.path();
            let relative = path
                .strip_prefix(&canonical_source)
                .map_err(|_| StorageError::InvalidData("project path escaped its root".into()))?;
            let normalized = relative.to_string_lossy().replace('\\', "/");
            let metadata = fs::symlink_metadata(&path).map_err(StorageError::Io)?;
            if direct_workspace_ignored_path(&normalized)
                || generated_agent_artifact_path(&normalized)
            {
                continue;
            }
            if sensitive_baseline_path(&normalized) {
                exclusions.push(mcg_domain::WorktreeBaselineExclusion {
                    normalized_path: normalized,
                    reason: "sensitive path excluded".into(),
                    review_blocker: true,
                });
                continue;
            }
            if metadata.file_type().is_symlink() {
                exclusions.push(mcg_domain::WorktreeBaselineExclusion {
                    normalized_path: normalized,
                    reason: "symlinked path excluded".into(),
                    review_blocker: true,
                });
                continue;
            }
            if metadata.is_dir() {
                pending.push(path);
                continue;
            }
            if !metadata.is_file() {
                continue;
            }
            if metadata.len() > 10 * 1024 * 1024 {
                exclusions.push(mcg_domain::WorktreeBaselineExclusion {
                    normalized_path: normalized,
                    reason: "file exceeds 10 MiB baseline limit".into(),
                    review_blocker: true,
                });
                continue;
            }
            if let Some(destination) = destination {
                let target = destination.join(relative);
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent).map_err(StorageError::Io)?;
                }
                fs::copy(&path, target).map_err(StorageError::Io)?;
            }
            entries.push(baseline_entry(
                &canonical_source,
                &normalized,
                mcg_domain::BaselineSourceKind::Untracked,
            )?);
        }
    }
    entries.sort_by(|left, right| left.normalized_path.cmp(&right.normalized_path));
    exclusions.sort_by(|left, right| left.normalized_path.cmp(&right.normalized_path));
    Ok((entries, exclusions))
}

fn direct_workspace_changed_files(worktree: &ManagedWorktree) -> Result<Vec<String>, StorageError> {
    let root = Path::new(&worktree.root);
    let (current, _) = direct_workspace_snapshot(root, None)?;
    let baseline = worktree
        .baseline_entries
        .iter()
        .map(|entry| (entry.normalized_path.as_str(), entry.sha256.as_str()))
        .collect::<BTreeMap<_, _>>();
    let current = current
        .iter()
        .map(|entry| (entry.normalized_path.as_str(), entry.sha256.as_str()))
        .collect::<BTreeMap<_, _>>();
    let mut changed = baseline
        .keys()
        .chain(current.keys())
        .filter(|path| baseline.get(**path) != current.get(**path))
        .map(|path| (*path).to_owned())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    changed.sort();
    Ok(changed)
}

fn normalized_git_paths(bytes: &[u8], label: &str) -> Result<Vec<String>, StorageError> {
    let mut paths = Vec::new();
    for value in bytes
        .split(|byte| *byte == 0)
        .filter(|value| !value.is_empty())
    {
        let value = std::str::from_utf8(value)
            .map_err(|_| StorageError::InvalidData(format!("{label} path is not UTF-8")))?;
        let path = Path::new(value);
        if path.is_absolute()
            || path.components().any(|component| {
                matches!(
                    component,
                    Component::ParentDir | Component::RootDir | Component::Prefix(_)
                )
            })
            || sensitive_baseline_path(value)
        {
            return Err(StorageError::InvalidData(format!(
                "{label} contains unsafe path {value}"
            )));
        }
        paths.push(value.replace('\\', "/"));
    }
    paths.sort();
    paths.dedup();
    Ok(paths)
}

fn regular_file_sha256(path: &Path) -> Result<Option<String>, StorageError> {
    if !path.exists() {
        return Ok(None);
    }
    let metadata = fs::symlink_metadata(path)?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err(StorageError::Conflict(format!(
            "{} is not a regular file",
            path.display()
        )));
    }
    Ok(Some(format!("{:x}", Sha256::digest(fs::read(path)?))))
}

fn git_content_id(repository: &Path, relative: &str) -> Result<Option<String>, StorageError> {
    let path = repository.join(relative);
    if !path.exists() {
        return Ok(None);
    }
    let metadata = fs::symlink_metadata(&path)?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err(StorageError::Conflict(format!(
            "{} is not a regular file",
            path.display()
        )));
    }
    let path_argument = format!("--path={relative}");
    let object = String::from_utf8(git_output(
        repository,
        &["hash-object", &path_argument, "--", relative],
    )?)
    .map_err(|_| StorageError::InvalidData("Git content identity was not UTF-8".into()))?
    .trim()
    .to_owned();
    if object.is_empty() {
        return Err(StorageError::InvalidData(format!(
            "Git did not return a content identity for {relative}"
        )));
    }
    Ok(Some(object))
}

fn combined_native_apply_output(result: &CodexCloudApplyResult) -> Option<String> {
    let stdout = result.stdout.trim();
    let stderr = result.stderr.trim();
    let value = match (stdout.is_empty(), stderr.is_empty()) {
        (true, true) => return None,
        (false, true) => stdout.to_owned(),
        (true, false) => stderr.to_owned(),
        (false, false) => format!("{stdout}\n{stderr}"),
    };
    Some(value.chars().take(16_384).collect())
}

fn validate_cloud_apply_overrides(
    config_overrides: &[String],
    enable_features: &[String],
    disable_features: &[String],
) -> Result<(), StorageError> {
    const GOVERNED: &[&str] = &[
        "agent",
        "agents",
        "app",
        "apps",
        "approval",
        "approval_policy",
        "browser",
        "computer_use",
        "credential",
        "credentials",
        "features",
        "hooks",
        "instructions",
        "mcp_servers",
        "model_provider",
        "model_providers",
        "network_access",
        "oss_provider",
        "permissions",
        "plugin",
        "plugins",
        "remote",
        "rules",
        "sandbox",
        "sandbox_mode",
        "shell_environment_policy",
        "skills",
        "tools",
        "workspace_write",
    ];
    if config_overrides.len() > 32
        || config_overrides.iter().map(String::len).sum::<usize>() > 16 * 1024
    {
        return Err(StorageError::InvalidData(
            "cloud apply configuration overrides exceed the 32-entry or 16 KiB limit".into(),
        ));
    }
    for expression in config_overrides {
        let (key, _) = expression.split_once('=').ok_or_else(|| {
            StorageError::InvalidData("Codex configuration overrides use KEY=VALUE".into())
        })?;
        if key.trim().is_empty() {
            return Err(StorageError::InvalidData(
                "Codex configuration override key cannot be empty".into(),
            ));
        }
        for segment in key.split('.') {
            let normalized = segment.trim().to_ascii_lowercase().replace('-', "_");
            let secret = ["api_key", "auth", "bearer", "password", "secret", "token"]
                .iter()
                .any(|needle| normalized.contains(needle));
            if normalized.is_empty() || secret || GOVERNED.contains(&normalized.as_str()) {
                return Err(StorageError::InvalidData(format!(
                    "Codex configuration `{key}` is governed by MetaCog and cannot be used for cloud apply"
                )));
            }
        }
    }
    let features = enable_features.iter().chain(disable_features);
    if enable_features.len().saturating_add(disable_features.len()) > 32 {
        return Err(StorageError::InvalidData(
            "cloud apply feature overrides exceed the 32-entry limit".into(),
        ));
    }
    for feature in features {
        if feature.is_empty()
            || !feature
                .bytes()
                .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
            || matches!(
                feature.as_str(),
                "shell_tool"
                    | "unified_exec"
                    | "multi_agent"
                    | "browser_use"
                    | "computer_use"
                    | "apps"
                    | "plugins"
                    | "image_generation"
                    | "workspace_dependencies"
            )
        {
            return Err(StorageError::InvalidData(format!(
                "Codex feature `{feature}` is invalid or governed by MetaCog"
            )));
        }
    }
    Ok(())
}

fn parse_delegation_argument(
    arguments: &serde_json::Value,
) -> Result<AgentDelegationId, RuntimeError> {
    arguments
        .get("delegation_id")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| StorageError::InvalidData("delegation_id is required".into()))?
        .parse()
        .map_err(|_| StorageError::InvalidData("invalid delegation_id".into()).into())
}

fn tool_content(arguments: &serde_json::Value) -> Result<String, RuntimeError> {
    let content = arguments
        .get("content")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .trim()
        .to_owned();
    if content.is_empty() || content.len() > 64 * 1024 {
        return Err(StorageError::InvalidData(
            "agent message must contain 1 to 65536 characters".into(),
        )
        .into());
    }
    Ok(content)
}

fn generated_coder_name(
    delegation_id: AgentDelegationId,
    used_names: &std::collections::HashSet<String>,
) -> String {
    const NAMES: [&str; 16] = [
        "Atlas", "Beacon", "Cedar", "Delta", "Ember", "Forge", "Grove", "Harbor", "Iris",
        "Juniper", "Kite", "Lumen", "Maple", "Nova", "Onyx", "Pioneer",
    ];
    let digest = Sha256::digest(delegation_id.to_string().as_bytes());
    let start = usize::from(digest[0]) % NAMES.len();
    for offset in 0..NAMES.len() {
        let candidate = format!("Coding Agent {}", NAMES[(start + offset) % NAMES.len()]);
        if !used_names.contains(&candidate) {
            return candidate;
        }
    }
    format!("Coding Agent {}", &delegation_id.to_string()[..8])
}

fn generated_tester_name(
    delegation_id: AgentDelegationId,
    used_names: &std::collections::HashSet<String>,
) -> String {
    const NAMES: [&str; 8] = [
        "Aster", "Cobalt", "Echo", "Indigo", "Quartz", "Scout", "Vega", "Willow",
    ];
    let digest = Sha256::digest(delegation_id.to_string().as_bytes());
    let start = usize::from(digest[1]) % NAMES.len();
    for offset in 0..NAMES.len() {
        let candidate = format!("Tester {}", NAMES[(start + offset) % NAMES.len()]);
        if !used_names.contains(&candidate) {
            return candidate;
        }
    }
    format!("Tester {}", &delegation_id.to_string()[..8])
}

fn effective_batch_revisions(
    batch: &CoordinationBatch,
    delegations: &[AgentDelegation],
) -> Vec<(AgentDelegationId, u64)> {
    let batch_delegations = batch
        .delegation_ids
        .iter()
        .filter_map(|id| delegations.iter().find(|item| item.id == *id))
        .collect::<Vec<_>>();
    let effective_ids = effective_delegation_attempt_ids(
        batch_delegations
            .iter()
            .map(|item| (item.id, item.retry_of_id)),
    );
    effective_ids
        .into_iter()
        .filter_map(|id| {
            batch_delegations
                .iter()
                .find(|item| item.id == id)
                .map(|item| (item.id, item.revision))
        })
        .collect()
}

fn chat_wake_idempotency_key(
    batch_id: CoordinationBatchId,
    revisions: &[(AgentDelegationId, u64)],
) -> String {
    let lineage = revisions
        .iter()
        .map(|(id, revision)| format!("{id}@{revision}"))
        .collect::<Vec<_>>()
        .join(",");
    let digest = Sha256::digest(lineage.as_bytes());
    format!("{batch_id}:chat_completion:{digest:x}")
}

fn final_review_wake_idempotency_key(batch_id: CoordinationBatchId) -> String {
    format!("{batch_id}:final_review")
}

fn sorted_delegation_revisions(delegations: &[AgentDelegation]) -> Vec<(AgentDelegationId, u64)> {
    let mut revisions = delegations
        .iter()
        .map(|item| (item.id, item.revision))
        .collect::<Vec<_>>();
    revisions.sort_by_key(|(id, _)| *id);
    revisions
}

fn codex_preferences(preferences: &ExecutionPreferences) -> CodexExecutionPreferences {
    CodexExecutionPreferences {
        model_provider: preferences.model_provider.clone(),
        model: preferences.model_id.clone(),
        effort: preferences.reasoning_effort.clone(),
        service_tier: preferences.service_tier.clone(),
        approval_mode: match preferences.approval_mode {
            mcg_domain::ApprovalMode::Ask => CodexApprovalMode::Ask,
            mcg_domain::ApprovalMode::AutoReview => CodexApprovalMode::AutoReview,
            mcg_domain::ApprovalMode::ReadOnly => CodexApprovalMode::ReadOnly,
            mcg_domain::ApprovalMode::FullAccess => CodexApprovalMode::FullAccess,
        },
        approval_policy: preferences.approval_policy.map(|policy| match policy {
            mcg_domain::ExecutionApprovalPolicy::Untrusted => CodexApprovalPolicy::Untrusted,
            mcg_domain::ExecutionApprovalPolicy::OnRequest => CodexApprovalPolicy::OnRequest,
            mcg_domain::ExecutionApprovalPolicy::Never => CodexApprovalPolicy::Never,
        }),
        sandbox_mode: preferences.sandbox_mode.map(|sandbox| match sandbox {
            mcg_domain::ExecutionSandboxMode::ReadOnly => CodexSandboxMode::ReadOnly,
            mcg_domain::ExecutionSandboxMode::WorkspaceWrite => CodexSandboxMode::WorkspaceWrite,
            mcg_domain::ExecutionSandboxMode::DangerFullAccess => {
                CodexSandboxMode::DangerFullAccess
            }
        }),
        permission_profile: preferences.permission_profile.clone(),
        writable_roots: preferences.additional_writable_roots.clone(),
        feature_overrides: preferences.codex_feature_overrides.clone(),
        config_overrides: codex_config_overrides(preferences),
        profile_config: preferences.codex_profile_config.clone(),
    }
}

fn specialist_codex_preferences(
    parent: &CodexExecutionPreferences,
    writable: bool,
    workspace_root: &str,
) -> CodexExecutionPreferences {
    let mut specialist = parent.clone();
    // A specialist's immutable lease and isolated worktree are its authority boundary. Never
    // route its routine sandboxed work through an owner-facing approval that the backstage
    // runtime cannot safely present, and never allow an approval to expand that sandbox.
    specialist.approval_mode = if writable {
        CodexApprovalMode::Ask
    } else {
        CodexApprovalMode::ReadOnly
    };
    specialist.approval_policy = Some(CodexApprovalPolicy::Never);
    specialist.sandbox_mode = Some(if writable {
        CodexSandboxMode::WorkspaceWrite
    } else {
        CodexSandboxMode::ReadOnly
    });
    specialist.permission_profile = None;
    specialist.writable_roots = if writable {
        vec![workspace_root.to_owned()]
    } else {
        Vec::new()
    };
    specialist
}

fn codex_config_path(key: &str) -> Result<Vec<String>, StorageError> {
    let mut table = toml::from_str::<toml::Table>(&format!("{key} = 0")).map_err(|error| {
        StorageError::InvalidData(format!("invalid Codex configuration key `{key}`: {error}"))
    })?;
    let mut path = Vec::new();
    loop {
        if table.len() != 1 {
            return Err(StorageError::InvalidData(format!(
                "Codex configuration key `{key}` must identify one dotted path"
            )));
        }
        let (segment, value) = table.into_iter().next().expect("single TOML path segment");
        if segment.trim().is_empty() {
            return Err(StorageError::InvalidData(
                "Codex configuration key segments cannot be empty".into(),
            ));
        }
        path.push(segment);
        match value {
            toml::Value::Table(next) => table = next,
            toml::Value::Integer(0) => break,
            _ => {
                return Err(StorageError::InvalidData(format!(
                    "Codex configuration key `{key}` is not a supported dotted path"
                )));
            }
        }
    }
    Ok(path)
}

fn codex_config_overrides(preferences: &ExecutionPreferences) -> Vec<CodexAppConfigOverride> {
    preferences
        .codex_config_overrides
        .iter()
        .filter_map(|value| {
            codex_config_path(&value.key)
                .ok()
                .map(|path| CodexAppConfigOverride {
                    path,
                    value: value.value.clone(),
                })
        })
        .collect()
}

const MAX_OUTPUT_SCHEMA_BYTES: usize = 64 * 1024;
const MAX_OUTPUT_SCHEMA_DEPTH: usize = 32;
const MAX_OUTPUT_SCHEMA_NODES: usize = 4_096;

fn validate_output_schema_value(
    value: &serde_json::Value,
    depth: usize,
    nodes: &mut usize,
) -> Result<(), StorageError> {
    *nodes = nodes.saturating_add(1);
    if *nodes > MAX_OUTPUT_SCHEMA_NODES {
        return Err(StorageError::InvalidData(format!(
            "output schema exceeds the {MAX_OUTPUT_SCHEMA_NODES}-node limit"
        )));
    }
    if depth > MAX_OUTPUT_SCHEMA_DEPTH {
        return Err(StorageError::InvalidData(format!(
            "output schema exceeds the {MAX_OUTPUT_SCHEMA_DEPTH}-level nesting limit"
        )));
    }
    match value {
        serde_json::Value::Array(values) => {
            for value in values {
                validate_output_schema_value(value, depth.saturating_add(1), nodes)?;
            }
        }
        serde_json::Value::Object(values) => {
            for value in values.values() {
                validate_output_schema_value(value, depth.saturating_add(1), nodes)?;
            }
        }
        _ => {}
    }
    Ok(())
}

fn validate_output_schema(preferences: &ExecutionPreferences) -> Result<(), StorageError> {
    let Some(schema) = preferences.output_schema.as_ref() else {
        return Ok(());
    };
    if !schema.is_object() {
        return Err(StorageError::InvalidData(
            "output schema must be a JSON object".into(),
        ));
    }
    let bytes = serde_json::to_vec(schema)
        .map_err(|error| StorageError::InvalidData(error.to_string()))?
        .len();
    if bytes > MAX_OUTPUT_SCHEMA_BYTES {
        return Err(StorageError::InvalidData(format!(
            "output schema exceeds the {MAX_OUTPUT_SCHEMA_BYTES}-byte limit"
        )));
    }
    let mut nodes = 0;
    validate_output_schema_value(schema, 0, &mut nodes)
}

fn validate_output_schema_mode(
    preferences: &ExecutionPreferences,
    mode: ConversationMode,
    requested_goal: bool,
    active_goal: bool,
) -> Result<(), StorageError> {
    if preferences.output_schema.is_some()
        && (mode == ConversationMode::Plan || requested_goal || active_goal)
    {
        return Err(StorageError::InvalidData(
            "structured output cannot be combined with Plan or an active Goal; return to normal chat first"
                .into(),
        ));
    }
    Ok(())
}

fn validate_execution_preferences(
    preferences: &mut ExecutionPreferences,
    has_project: bool,
) -> Result<(), RuntimeError> {
    // Profile snapshots are runtime-owned. Never trust serialized values supplied by an API or
    // CLI caller; each originating send resolves the named profile again before persistence.
    preferences.codex_profile_config = None;
    preferences.codex_profile_digest = None;
    preferences.codex_profile_ignored_keys.clear();
    if let Some(provider) = preferences.model_provider.as_mut() {
        *provider = provider.trim().to_ascii_lowercase();
        let default_model = match provider.as_str() {
            "ollama" => "gpt-oss:20b",
            "lmstudio" => "openai/gpt-oss-20b",
            _ => {
                return Err(StorageError::InvalidData(
                    "Codex local provider must be `ollama` or `lmstudio`".into(),
                )
                .into());
            }
        };
        if preferences.model_id.as_deref().is_none_or(str::is_empty) {
            preferences.model_id = Some(default_model.into());
        }
        // Local providers do not have an OpenAI subscription service tier.
        preferences.service_tier = None;
    }
    validate_output_schema(preferences)?;
    if let Some(profile) = preferences.codex_profile.as_mut() {
        *profile = profile.trim().to_owned();
        if profile.is_empty()
            || profile.len() > 128
            || matches!(profile.as_str(), "." | "..")
            || !profile
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
        {
            return Err(StorageError::InvalidData(
                "Codex profile must use 1-128 letters, numbers, dashes, underscores, or dots"
                    .into(),
            )
            .into());
        }
    }
    if let Some(profile) = preferences.permission_profile.as_mut() {
        *profile = profile.trim().to_owned();
        if profile.is_empty()
            || profile.len() > 128
            || !profile.bytes().all(|byte| {
                byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b':')
            })
        {
            return Err(StorageError::InvalidData(
                "Codex permission profile must be a non-empty identifier using letters, numbers, dash, underscore, dot, or colon".into(),
            )
            .into());
        }
        if !has_project {
            return Err(StorageError::InvalidData(
                "Codex permission profiles require a linked project".into(),
            )
            .into());
        }
        if preferences.sandbox_mode.is_some() {
            return Err(StorageError::InvalidData(
                "a Codex permission profile cannot be combined with an explicit sandbox mode"
                    .into(),
            )
            .into());
        }
    }
    const MAX_CODEX_FEATURE_OVERRIDES: usize = 32;
    const GOVERNED_CODEX_FEATURES: &[&str] = &[
        "shell_tool",
        "unified_exec",
        "multi_agent",
        "enable_fanout",
        "browser_use",
        "browser_use_external",
        "browser_use_full_cdp_access",
        "in_app_browser",
        "computer_use",
        "apps",
        "plugins",
        "image_generation",
        "workspace_dependencies",
    ];
    if preferences.codex_feature_overrides.len() > MAX_CODEX_FEATURE_OVERRIDES {
        return Err(StorageError::InvalidData(format!(
            "at most {MAX_CODEX_FEATURE_OVERRIDES} Codex feature overrides are allowed per run"
        ))
        .into());
    }
    for feature in preferences.codex_feature_overrides.keys() {
        if feature.is_empty()
            || !feature
                .bytes()
                .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
        {
            return Err(StorageError::InvalidData(format!(
                "invalid Codex feature name `{feature}`; use lowercase letters, numbers, and underscores"
            ))
            .into());
        }
        if GOVERNED_CODEX_FEATURES.contains(&feature.as_str()) {
            return Err(StorageError::InvalidData(format!(
                "Codex feature `{feature}` is governed by MetaCog and cannot be overridden per run"
            ))
            .into());
        }
    }
    const MAX_CODEX_CONFIG_OVERRIDES: usize = 32;
    const MAX_CODEX_CONFIG_BYTES: usize = 16 * 1024;
    const GOVERNED_CONFIG_SEGMENTS: &[&str] = &[
        "agent",
        "agents",
        "app",
        "apps",
        "approval",
        "approval_policy",
        "browser",
        "computer_use",
        "credential",
        "credentials",
        "developer_instructions",
        "dynamic_tools",
        "experimental_user_input",
        "features",
        "hooks",
        "instructions",
        "mcp_servers",
        "model_provider",
        "model_providers",
        "network_access",
        "oss_provider",
        "permissions",
        "plugin",
        "plugins",
        "process",
        "remote",
        "rules",
        "sandbox",
        "sandbox_mode",
        "shell_environment_policy",
        "skills",
        "show_raw_agent_reasoning",
        "tools",
        "user_instructions",
        "workspace_write",
    ];
    if preferences.codex_config_overrides.len() > MAX_CODEX_CONFIG_OVERRIDES {
        return Err(StorageError::InvalidData(format!(
            "at most {MAX_CODEX_CONFIG_OVERRIDES} Codex configuration overrides are allowed per run"
        ))
        .into());
    }
    let serialized_config_bytes = serde_json::to_vec(&preferences.codex_config_overrides)
        .map_err(|error| StorageError::InvalidData(error.to_string()))?
        .len();
    if serialized_config_bytes > MAX_CODEX_CONFIG_BYTES {
        return Err(StorageError::InvalidData(format!(
            "Codex configuration overrides exceed the {MAX_CODEX_CONFIG_BYTES}-byte per-run limit"
        ))
        .into());
    }
    for config_override in &preferences.codex_config_overrides {
        let path = codex_config_path(config_override.key.trim())?;
        if path.as_slice() == ["web_search"]
            && !matches!(
                config_override.value.as_str(),
                Some("cached" | "live" | "disabled")
            )
        {
            return Err(StorageError::InvalidData(
                "Codex configuration `web_search` must be `cached`, `live`, or `disabled`".into(),
            )
            .into());
        }
        for segment in &path {
            let normalized = segment.to_ascii_lowercase().replace('-', "_");
            let contains_secret = [
                "api_key",
                "auth",
                "bearer",
                "credential",
                "password",
                "secret",
                "token",
            ]
            .iter()
            .any(|needle| normalized.contains(needle));
            if contains_secret || GOVERNED_CONFIG_SEGMENTS.contains(&normalized.as_str()) {
                return Err(StorageError::InvalidData(format!(
                    "Codex configuration `{}` is governed by MetaCog and cannot be overridden per run",
                    config_override.key
                ))
                .into());
            }
        }
    }
    const MAX_ADDITIONAL_WRITABLE_ROOTS: usize = 16;
    if preferences.additional_writable_roots.len() > MAX_ADDITIONAL_WRITABLE_ROOTS {
        return Err(StorageError::InvalidData(format!(
            "at most {MAX_ADDITIONAL_WRITABLE_ROOTS} additional writable directories are allowed"
        ))
        .into());
    }
    if !has_project && !preferences.additional_writable_roots.is_empty() {
        return Err(StorageError::InvalidData(
            "additional writable directories require a linked project".into(),
        )
        .into());
    }
    if !preferences.additional_writable_roots.is_empty()
        && (preferences.approval_mode == mcg_domain::ApprovalMode::ReadOnly
            || matches!(
                preferences.sandbox_mode,
                Some(mcg_domain::ExecutionSandboxMode::ReadOnly)
            ))
    {
        return Err(StorageError::InvalidData(
            "additional writable directories cannot be combined with a read-only sandbox".into(),
        )
        .into());
    }
    let mut normalized = Vec::with_capacity(preferences.additional_writable_roots.len());
    let mut identities = BTreeSet::new();
    for root in &preferences.additional_writable_roots {
        if root.trim().is_empty() {
            return Err(StorageError::InvalidData(
                "additional writable directory cannot be empty".into(),
            )
            .into());
        }
        let canonical = fs::canonicalize(root).map_err(|error| {
            StorageError::InvalidData(format!(
                "additional writable directory `{root}` is unavailable: {error}"
            ))
        })?;
        if !canonical.is_dir() {
            return Err(StorageError::InvalidData(format!(
                "additional writable path is not a directory: {}",
                canonical.display()
            ))
            .into());
        }
        let value = canonical.to_str().ok_or_else(|| {
            StorageError::InvalidData(
                "additional writable directory paths must be valid Unicode".into(),
            )
        })?;
        #[cfg(windows)]
        let identity = value.to_lowercase();
        #[cfg(not(windows))]
        let identity = value.to_owned();
        if identities.insert(identity) {
            normalized.push(value.to_owned());
        }
    }
    preferences.additional_writable_roots = normalized;
    Ok(())
}

fn execution_is_read_only(preferences: &ExecutionPreferences) -> bool {
    preferences.approval_mode == mcg_domain::ApprovalMode::ReadOnly
        || preferences.sandbox_mode == Some(mcg_domain::ExecutionSandboxMode::ReadOnly)
}

fn effective_delegation_permission_mode(
    preferences: &ExecutionPreferences,
) -> mcg_domain::ApprovalMode {
    if execution_is_read_only(preferences) {
        mcg_domain::ApprovalMode::ReadOnly
    } else {
        preferences.approval_mode
    }
}

fn coder_report_template(
    success_conditions: &[String],
    integration_ready: bool,
) -> serde_json::Result<String> {
    let requirement_evidence = success_conditions
        .iter()
        .map(|requirement| {
            serde_json::json!({
                "requirement": requirement,
                "satisfied": true,
                "evidence": "<replace with concrete observable evidence>",
                "verification": "<replace with the exact test, command, inspection, or workflow>"
            })
        })
        .collect::<Vec<_>>();
    serde_json::to_string_pretty(&serde_json::json!({
        "summary": "<replace with a concise verified result>",
        "changed_files": [],
        "checks": ["<replace with at least one completed verification check>"],
        "evidence": ["<replace with at least one concrete evidence item>"],
        "requirement_evidence": requirement_evidence,
        "unresolved_issues": [],
        "integration_ready": integration_ready
    }))
}

fn outer_settlement_success_condition(condition: &str) -> bool {
    let words = condition
        .split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
        .filter(|word| !word.is_empty())
        .map(str::to_ascii_lowercase)
        .collect::<Vec<_>>();
    let has = |expected: &str| words.iter().any(|word| word == expected);
    let outer_completion = ["complete", "completed", "completion", "finish", "finished"]
        .iter()
        .any(|word| has(word));
    let outer_subject = ["task", "request", "conversation"]
        .iter()
        .any(|word| has(word))
        || has("batch");
    let report_settlement = (has("report") || has("report_result"))
        && ["accept", "accepted", "acceptance"]
            .iter()
            .any(|word| has(word));
    let integration_settlement = has("integration")
        && [
            "complete",
            "completed",
            "completion",
            "settled",
            "settlement",
        ]
        .iter()
        .any(|word| has(word));
    let owner_delivery = has("owner")
        && [
            "receive",
            "receives",
            "received",
            "delivery",
            "delivered",
            "final",
        ]
        .iter()
        .any(|word| has(word));

    (outer_subject && outer_completion)
        || report_settlement
        || integration_settlement
        || owner_delivery
}

fn validate_specialist_brief(brief: &CodingDelegationBrief) -> Result<(), StorageError> {
    if let Some(condition) = brief
        .success_conditions
        .iter()
        .find(|condition| outer_settlement_success_condition(condition))
    {
        return Err(StorageError::InvalidData(format!(
            "specialist success condition depends on outer settlement and cannot be verified before report_result: {condition}. Replace it with a concrete observable deliverable"
        )));
    }
    Ok(())
}

fn effective_parallel_specialist_limit(
    preferences: &ExecutionPreferences,
    organization: &OrganizationGenome,
) -> u16 {
    let organization_limit = organization.policy.max_parallel_agents.min(8);
    preferences
        .team_preset
        .parallel_specialist_limit()
        .map_or(organization_limit, |preset_limit| {
            organization_limit.min(preset_limit)
        })
}

struct ActiveCoordinationBatchGuard<'a> {
    batches: &'a Mutex<BTreeMap<ConversationId, CoordinationBatchId>>,
    conversation_id: ConversationId,
}

struct LiveConversationPreview {
    shutdown: oneshot::Sender<()>,
}

#[derive(Clone)]
struct ProjectMentionCache {
    fingerprint: String,
    candidates: Vec<MentionCandidate>,
}

struct QueuedConversationAcceptance {
    sender: Option<tokio::sync::oneshot::Sender<Result<(), String>>>,
    turn_id: Option<ConversationTurnId>,
}

impl Drop for ActiveCoordinationBatchGuard<'_> {
    fn drop(&mut self) {
        if let Ok(mut batches) = self.batches.lock() {
            batches.remove(&self.conversation_id);
        }
    }
}

