    pub async fn start_owned_codex_review(
        &self,
        conversation_id: ConversationId,
        target: CodexReviewTarget,
        delivery: CodexReviewDelivery,
    ) -> Result<CodexReviewResult, RuntimeError> {
        // Chat, Coordinator, and specialist role threads intentionally run in private scratch or
        // isolated worktree directories and are archived while idle. Reusing whichever role last
        // wrote the conversation binding made `review/start` target an archived, usually non-Git
        // cwd and surfaced as an opaque 500. A review receives its own read-only project-rooted
        // thread so role authority, instructions, cwd, and lifecycle never bleed into one another.
        let conversation = self.conversation(conversation_id)?.conversation;
        let project_id = conversation.project_id.ok_or_else(|| {
            StorageError::InvalidData("code review requires a project-bound conversation".into())
        })?;
        let project = self.project(project_id)?.ok_or_else(|| {
            StorageError::InvalidData("code review project is no longer available".into())
        })?;
        if !project.repository.is_git {
            return Err(StorageError::InvalidData(
                "code review requires a Git-backed project".into(),
            )
            .into());
        }
        let project_root = fs::canonicalize(&project.root).map_err(|error| {
            StorageError::InvalidData(format!("code review project cannot be resolved: {error}"))
        })?;
        let project_root = project_root.to_string_lossy().into_owned();
        let codex_harness = self.codex_harness_for_conversation(conversation_id);
        let mut preferences = self.codex_preferences_for_conversation(
            conversation_id,
            &conversation.execution_preferences,
        );
        preferences.approval_mode = CodexApprovalMode::Ask;
        preferences.approval_policy = None;
        preferences.sandbox_mode = Some(CodexSandboxMode::ReadOnly);
        preferences.permission_profile = None;
        preferences.writable_roots.clear();
        let host_thread_id = codex_harness
            .start_thread(Some(&project_root), &preferences, false)
            .await?;
        match codex_harness
            .start_review(&host_thread_id, target, delivery)
            .await
        {
            Ok(result) => {
                if delivery == CodexReviewDelivery::Detached {
                    let _ = codex_harness.archive_thread(&host_thread_id).await;
                    let _ = codex_harness.unsubscribe_thread(&host_thread_id).await;
                }
                Ok(result)
            }
            Err(error) => {
                let _ = codex_harness.archive_thread(&host_thread_id).await;
                let _ = codex_harness.unsubscribe_thread(&host_thread_id).await;
                Err(error.into())
            }
        }
    }

    pub async fn exec_governed_codex_command(
        &self,
        conversation_id: ConversationId,
        request: CodexCommandExecRequest,
    ) -> Result<CodexCommandExecResult, RuntimeError> {
        let request = self.prepare_governed_codex_command(conversation_id, request)?;
        Ok(self
            .codex_harness_for_conversation(conversation_id)
            .exec_command(request)
            .await?)
    }

    fn prepare_governed_codex_command(
        &self,
        conversation_id: ConversationId,
        mut request: CodexCommandExecRequest,
    ) -> Result<CodexCommandExecRequest, RuntimeError> {
        let root = self.conversation_project_root(conversation_id)?;
        let cwd = match request.cwd.as_deref() {
            Some(cwd) => fs::canonicalize(cwd).map_err(|error| {
                StorageError::InvalidData(format!("command cwd cannot be resolved: {error}"))
            })?,
            None => root.clone(),
        };
        if !cwd.starts_with(&root) {
            return Err(StorageError::InvalidData(
                "command cwd must remain inside the conversation project".into(),
            )
            .into());
        }
        request.cwd = Some(cwd.to_string_lossy().into_owned());
        Ok(request)
    }

    pub async fn start_conversation_command(
        self: &Arc<Self>,
        conversation_id: ConversationId,
        mut request: CodexCommandExecRequest,
    ) -> Result<ConversationCommandExecution, RuntimeError> {
        let id = Uuid::new_v4().to_string();
        request.process_id = Some(id.clone());
        let request = self.prepare_governed_codex_command(conversation_id, request)?;
        let execution = ConversationCommandExecution {
            id: id.clone(),
            conversation_id,
            command: request.command.clone(),
            cwd: request.cwd.clone().unwrap_or_default(),
            state: ConversationCommandState::Running,
            exit_code: None,
            stdout: String::new(),
            stderr: String::new(),
            started_at: Utc::now(),
            completed_at: None,
        };
        self.conversation_commands
            .lock()
            .await
            .insert(id.clone(), execution.clone());
        let runtime = self.clone();
        let codex_harness = self.codex_harness_for_conversation(conversation_id);
        tokio::spawn(async move {
            let result = codex_harness.exec_command(request).await;
            let mut commands = runtime.conversation_commands.lock().await;
            let Some(execution) = commands.get_mut(&id) else {
                return;
            };
            execution.completed_at = Some(Utc::now());
            match result {
                Ok(result) => {
                    execution.exit_code = Some(result.exit_code);
                    execution.stdout = result.stdout;
                    execution.stderr = result.stderr;
                    execution.state = if execution.state == ConversationCommandState::Stopping {
                        ConversationCommandState::Stopped
                    } else if result.exit_code == 0 {
                        ConversationCommandState::Succeeded
                    } else {
                        ConversationCommandState::Failed
                    };
                }
                Err(error) => {
                    execution.stderr = error.to_string();
                    execution.state = if execution.state == ConversationCommandState::Stopping {
                        ConversationCommandState::Stopped
                    } else {
                        ConversationCommandState::Failed
                    };
                }
            }
        });
        Ok(execution)
    }

    pub async fn conversation_commands(
        &self,
        conversation_id: ConversationId,
    ) -> Result<Vec<ConversationCommandExecution>, RuntimeError> {
        self.conversation(conversation_id)?;
        Ok(self
            .conversation_commands
            .lock()
            .await
            .values()
            .filter(|execution| execution.conversation_id == conversation_id)
            .cloned()
            .collect())
    }

    pub async fn stop_conversation_command(
        &self,
        conversation_id: ConversationId,
        command_id: &str,
    ) -> Result<ConversationCommandExecution, RuntimeError> {
        self.conversation(conversation_id)?;
        {
            let mut commands = self.conversation_commands.lock().await;
            let execution = commands.get_mut(command_id).ok_or_else(|| {
                StorageError::InvalidData("conversation command was not found".into())
            })?;
            if execution.conversation_id != conversation_id {
                return Err(StorageError::InvalidData(
                    "conversation command belongs to another conversation".into(),
                )
                .into());
            }
            if execution.state != ConversationCommandState::Running {
                return Err(StorageError::Conflict(
                    "conversation command is no longer running".into(),
                )
                .into());
            }
            execution.state = ConversationCommandState::Stopping;
        }
        self.codex_harness_for_conversation(conversation_id)
            .terminate_command(command_id)
            .await?;
        Ok(self
            .conversation_commands
            .lock()
            .await
            .get(command_id)
            .cloned()
            .ok_or_else(|| StorageError::InvalidData("conversation command was lost".into()))?)
    }

