    /// Discovers a project from its canonical repository root and durably records
    /// the snapshot before publishing its event.
    ///
    /// # Errors
    ///
    /// Returns an error for inaccessible roots, invalid manifests, root identity
    /// conflicts, or failed persistence.
    pub fn discover_project(
        &self,
        root: &Path,
        project_id: ProjectId,
    ) -> Result<ProjectMutation, RuntimeError> {
        self.discover_project_with_git(root, project_id, false)
    }

    /// Discovers a project and, when explicitly requested, safely creates local
    /// Git metadata for an eligible plain folder before taking the snapshot.
    pub fn discover_project_with_git(
        &self,
        root: &Path,
        project_id: ProjectId,
        initialize_git: bool,
    ) -> Result<ProjectMutation, RuntimeError> {
        if initialize_git {
            initialize_local_git_repository(root)?;
        }
        let mut project = ProjectDiscoverer::discover(root, project_id)?;
        // Root identity is durable across archive/removal. Rediscovering a path that
        // the owner previously removed revives its original project ID and history
        // instead of failing the unique-root constraint or forking catalog identity.
        if let Some(existing) = self.store()?.catalog_project_by_root(&project.root)? {
            if existing.project_id != project.project_id {
                project = ProjectDiscoverer::discover(root, existing.project_id)?;
            }
        }
        let previous = self.store()?.project(project.project_id)?;
        let invalidation = previous
            .as_ref()
            .map(|previous| SnapshotInvalidation::between(previous, &project).into());
        let event = self.store()?.record_project_snapshot(&project)?;
        let _ = self.event_sender.send(event.clone());
        Ok(ProjectMutation {
            project,
            event,
            invalidation,
        })
    }

    /// Initializes the current project root as a local Git repository and
    /// records a fresh durable project snapshot.
    pub fn initialize_project_git(
        &self,
        project_id: ProjectId,
    ) -> Result<ProjectMutation, RuntimeError> {
        let project = self
            .project(project_id)?
            .ok_or_else(|| StorageError::ProjectNotFound(project_id))?;
        self.discover_project_with_git(Path::new(&project.root), project_id, true)
    }

