    #[test]
    fn team_presets_intersect_with_pinned_organization_capacity() {
        let mut organization = OrganizationGenome::consumer_default(Utc::now());
        organization.policy.max_parallel_agents = 6;
        let mut preferences = ExecutionPreferences::default();

        assert_eq!(
            effective_parallel_specialist_limit(&preferences, &organization),
            6
        );
        preferences.team_preset = mcg_domain::TeamPreset::Fast;
        assert_eq!(
            effective_parallel_specialist_limit(&preferences, &organization),
            1
        );
        preferences.team_preset = mcg_domain::TeamPreset::Balanced;
        assert_eq!(
            effective_parallel_specialist_limit(&preferences, &organization),
            3
        );
        preferences.team_preset = mcg_domain::TeamPreset::Thorough;
        assert_eq!(
            effective_parallel_specialist_limit(&preferences, &organization),
            6
        );

        organization.policy.max_parallel_agents = 2;
        preferences.team_preset = mcg_domain::TeamPreset::Balanced;
        assert_eq!(
            effective_parallel_specialist_limit(&preferences, &organization),
            2
        );
    }

    #[tokio::test]
    async fn static_conversation_preview_is_loopback_only_and_rejects_traversal() {
        let root = tempfile::tempdir().expect("preview root");
        fs::write(root.path().join("index.html"), "<h1>Preview ready</h1>").expect("entry");
        let listener = TcpListener::bind("127.0.0.1:0").await.expect("bind");
        let address = listener.local_addr().expect("address");
        assert!(address.ip().is_loopback());
        let (shutdown, receiver) = oneshot::channel();
        let canonical = fs::canonicalize(root.path()).expect("canonical root");
        let server = tokio::spawn(run_static_conversation_preview(
            listener,
            canonical,
            "index.html".into(),
            receiver,
        ));

        let mut stream = TcpStream::connect(address).await.expect("connect");
        stream
            .write_all(b"GET / HTTP/1.1\r\nHost: 127.0.0.1\r\n\r\n")
            .await
            .expect("request");
        let mut response = Vec::new();
        stream.read_to_end(&mut response).await.expect("response");
        let response = String::from_utf8(response).expect("utf8 response");
        assert!(response.starts_with("HTTP/1.1 200 OK"));
        assert!(response.contains("Preview ready"));
        assert!(response.contains("Cache-Control: no-store"));

        let mut stream = TcpStream::connect(address)
            .await
            .expect("connect traversal");
        stream
            .write_all(b"GET /../secret HTTP/1.1\r\nHost: 127.0.0.1\r\n\r\n")
            .await
            .expect("traversal request");
        let mut response = Vec::new();
        stream
            .read_to_end(&mut response)
            .await
            .expect("traversal response");
        assert!(
            String::from_utf8(response)
                .expect("utf8 traversal response")
                .starts_with("HTTP/1.1 400 Bad Request")
        );

        let _ = shutdown.send(());
        server.await.expect("server shutdown");
    }

